(function () {
	const FIELDS = { name: "full_name_aadhaar", dob: "dob", phone: "phone_number", email: "email_address" };

	function check_duplicate(frm) {
		const full_name = frm.doc[FIELDS.name];
		const dob = frm.doc[FIELDS.dob];
		const phone = frm.doc[FIELDS.phone];
		const email = frm.doc[FIELDS.email];

		if (!(full_name && dob && phone && email)) return;

		frappe.call({
			method: "ms_calendar.api.ms_field.check_duplicate_registration",
			args: {
				full_name: full_name,
				date_of_birth: dob,
				phone_number: phone,
				email_address: email,
				exclude_doctype: frm.is_new() ? null : frm.doctype,
				exclude_name: frm.is_new() ? null : frm.doc.name,
			},
			callback: function (r) {
				if (r.message && r.message.duplicate) {
					frappe.msgprint({
						title: __("Possible Duplicate Application"),
						indicator: "orange",
						message: __(
							"An application with the same Name, Date of Birth, Phone Number and Email already exists ({0} {1}). They may already have an application submitted for this recruitment process.",
							[r.message.doctype, r.message.name]
						),
					});
				}
			},
		});
	}

	frappe.ui.form.on("Field Registration Form", {
		"full_name_aadhaar": check_duplicate,
		"dob": check_duplicate,
		"phone_number": check_duplicate,
		"email_address": check_duplicate,
		refresh: check_duplicate,
	});
})();

